      <Text bold>{t!.goal}</Text>
      {text.split('\n').map(l => (
        <Text color={lineColor(l)} bold={l.startsWith('+++') || l.startsWith('---')} wrap="truncate-end">
          {l === '' ? ' ' : l}
        </Text>
      ))}
